class MultimodalSinusoidalBenchmark:
    def __init__(self, dim):
        self.dim = dim
        self.bounds = type('Bounds', (), {'lb': -5.0, 'ub': 5.0})()

    def f(self, x):
        if len(x) != self.dim:
            raise ValueError("Input dimension mismatch")

        # Base quadratic term
        f = np.sum(x**2)

